import{_ as t,o,c as r,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const f=JSON.parse('{"title":"How OrbySystems is different","description":"","frontmatter":{"title":"How OrbySystems is different"},"headers":[],"relativePath":"docs/overview/how-orby-is-different.md","filePath":"docs/overview/how-orby-is-different.md","lastUpdated":1793072112000}'),a={name:"docs/overview/how-orby-is-different.md"};function s(i,e,d,l,h,c){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="how-orbysystems-is-different" tabindex="-1">How OrbySystems is different <a class="header-anchor" href="#how-orbysystems-is-different" aria-label="Permalink to &quot;How OrbySystems is different&quot;">​</a></h1><h2 id="no-forced-cloud-dependency" tabindex="-1">No forced cloud dependency <a class="header-anchor" href="#no-forced-cloud-dependency" aria-label="Permalink to &quot;No forced cloud dependency&quot;">​</a></h2><p>You can run OrbySystems entirely offline with a local model. Connecting a cloud model is optional, for when you want it — never a requirement to get started.</p><h2 id="you-don-t-trust-the-llm-neither-do-we" tabindex="-1">You don&#39;t trust the LLM. Neither do we. <a class="header-anchor" href="#you-don-t-trust-the-llm-neither-do-we" aria-label="Permalink to &quot;You don&#39;t trust the LLM. Neither do we.&quot;">​</a></h2><p>An LLM can be wrong, or tricked by something it reads, so OrbySystems never gives it the run of your machine. Unlike a general-purpose agent, OrbySystems&#39;s model always runs locked down inside a sandbox, limited to exactly what it needs to see on disk and connect to over the network to do its job — it will never see files in your home directory outside that sandbox, and it can only reach the small set of external servers needed to maintain its own sandboxed tools — see the allowed-hosts whitelist in <a href="/docs/settings/agent">Settings → Agent → Sandbox</a>.</p><h2 id="untrusted-content-runs-isolated" tabindex="-1">Untrusted content runs isolated <a class="header-anchor" href="#untrusted-content-runs-isolated" aria-label="Permalink to &quot;Untrusted content runs isolated&quot;">​</a></h2><p>Anything that processes content you didn&#39;t write yourself — a statement parser, a generated script — runs in that same isolated sandbox, never with direct access to the rest of your system.</p><h2 id="an-extensible-contributable-core" tabindex="-1">An extensible, contributable core <a class="header-anchor" href="#an-extensible-contributable-core" aria-label="Permalink to &quot;An extensible, contributable core&quot;">​</a></h2><p>Not every bank or brokerage statement format is recognized out of the box. When OrbySystems doesn&#39;t recognize one, <a href="/docs/tools/add-new-institution">Add New Institution</a> makes a scrambled copy of your statement, with your names and numbers replaced, and OrbySystems builds a parser from that copy alone, and tries the result on your real statement before installing it.</p><h2 id="free-with-plus-for-the-long-view" tabindex="-1">Free, with Plus for the long view <a class="header-anchor" href="#free-with-plus-for-the-long-view" aria-label="Permalink to &quot;Free, with Plus for the long view&quot;">​</a></h2><p>OrbySystems is free to use with no account, for any six months of your statements at a time. Plus analyses every year you&#39;ve covered, and pays for the work behind OrbySystems. See <a href="https://orbysystems.ai/plans" target="_blank" rel="noreferrer">Plans</a>.</p>',11)])])}const y=t(a,[["render",s]]);export{f as __pageData,y as default};
